// T134: the host's C64 key matrix (keys[col*8+row], 1 = down) into the PET graphics-keyboard matrix (10 rows x 8 columns, a pressed key reads 0).
// Generated by cores/pet/sim/gen_keys.py (its table is the source; do not edit by hand). Positional by legend: the PET's symbol keys
// ! " # $ % ' & \ ( ) sit on the C64's 1..0, the PET keypad digits are C= + digit, either SHIFT is the PET shift (row 8, column 5, as in the
// MiSTer port), C64 F7/F3/F5/F1 stand in for the PET keys / . < [ that the C64 has no counterpart for. The business matrix (bus = 1, the CRTC models) is from VICE's gtk3_buuk_pos.vkm.
`timescale 1ns / 1ps
module pet_keys (
    input  wire [63:0] keys,
    input  wire        bus,                 // 1: the business keyboard (the CRTC models)
    input  wire [3:0]  keyrow,
    output wire [7:0]  keyin
);
    wire dig = keys[56] | keys[59] | keys[8] | keys[11] | keys[16] | keys[19] | keys[24] | keys[27] | keys[32] | keys[35];
    reg [7:0] r, rb;
    always @* begin
        case (keyrow)
            4'd0: r = {keys[2], keys[51], keys[57], (keys[32] & ~keys[61]), (keys[24] & ~keys[61]), (keys[16] & ~keys[61]), (keys[8] & ~keys[61]), (keys[56] & ~keys[61])};
            4'd1: r = {keys[0], keys[7], 1'b0, (keys[35] & ~keys[61]), (keys[27] & ~keys[61]), (keys[19] & ~keys[61]), (keys[11] & ~keys[61]), (keys[59] & ~keys[61])};
            4'd2: r = {(keys[32] & keys[61]), (keys[24] & keys[61]), keys[54], keys[38], keys[30], keys[22], keys[14], keys[62]};
            4'd3: r = {keys[3], (keys[27] & keys[61]), 1'b0, keys[41], keys[33], keys[25], keys[17], keys[9]};
            4'd4: r = {(keys[19] & keys[61]), (keys[11] & keys[61]), 1'b0, keys[42], keys[34], keys[26], keys[18], keys[10]};
            4'd5: r = {keys[49], (keys[16] & keys[61]), 1'b0, keys[45], keys[37], keys[29], keys[21], keys[13]};
            4'd6: r = {(keys[8] & keys[61]), (keys[56] & keys[61]), keys[1], keys[50], keys[36], keys[28], keys[20], keys[12]};
            4'd7: r = {keys[40], (keys[59] & keys[61]), 1'b0, keys[55], keys[47], keys[39], keys[31], keys[23]};
            4'd8: r = {keys[43], (keys[35] & keys[61]), (keys[15] | keys[52]), keys[44], 1'b0, keys[48], keys[46], (keys[61] & ~dig)};
            4'd9: r = {keys[53], keys[5], 1'b0, keys[63], keys[6], keys[60], keys[4], keys[58]};
            default: r = 8'h00;
        endcase
        case (keyrow)
            4'd0: rb = {1'b0, 1'b0, keys[2], (keys[27] & keys[61]), keys[43], (keys[27] & ~keys[61]), (keys[16] & ~keys[61]), (keys[59] & ~keys[61])};
            4'd1: rb = {(keys[32] & keys[61]), 1'b0, keys[54], (keys[24] & keys[61]), (keys[35] & ~keys[61]), (keys[24] & ~keys[61]), (keys[11] & ~keys[61]), (keys[56] & ~keys[61])};
            4'd2: rb = {(keys[16] & keys[61]), keys[50], keys[37], keys[53], keys[29], keys[21], keys[13], keys[4]};
            4'd3: rb = {(keys[19] & keys[61]), keys[46], keys[42], keys[1], keys[34], keys[26], keys[18], keys[10]};
            4'd4: rb = {keys[0], keys[41], keys[33], keys[48], keys[25], keys[17], keys[9], keys[6]};
            4'd5: rb = {(keys[11] & keys[61]), keys[40], keys[38], keys[7], keys[30], keys[22], keys[14], keys[62]};
            4'd6: rb = {(keys[8] & keys[61]), 1'b0, 1'b0, (keys[44] & keys[61]), (keys[44] & ~keys[61]), keys[28], keys[20], (keys[15] | keys[52])};
            4'd7: rb = {(keys[59] & keys[61]), keys[3], 1'b0, (keys[35] & keys[61]), (keys[47] & ~keys[61]), keys[39], keys[31], keys[12]};
            4'd8: rb = {(keys[56] & keys[61]), keys[55], 1'b0, keys[51], keys[36], keys[60], keys[23], keys[5]};
            4'd9: rb = {1'b0, 1'b0, keys[45], keys[63], (keys[32] & ~keys[61]), (keys[19] & ~keys[61]), (keys[8] & ~keys[61]), keys[57]};
            default: rb = 8'h00;
        endcase
    end
    assign keyin = bus ? ~rb : ~r;
endmodule
